package ro.leo.visual;
import android.content.*;import java.util.*;
/** Android tasks are queried off the UI thread; shell/media services are preserved. */
public final class RecentAppsActivity extends LeoActivity {
 private int generation;private ArrayList<TaskActions.Entry> tasks=new ArrayList<>();private ArrayList<Integer> leo=new ArrayList<>();
 protected void onResume(){super.onResume();show();}
 protected void onPause(){generation++;super.onPause();}
 private void show(){final int token=++generation;begin("Aplicații recente");root.addView(text("Se citesc ferestrele…",17),new android.widget.LinearLayout.LayoutParams(-1,0,1));footer("","","Înapoi");worker.execute(new Runnable(){public void run(){try{final ArrayList<TaskActions.Entry> found=TaskActions.recent(RecentAppsActivity.this);ui(new Runnable(){public void run(){if(token==generation){tasks=found;render();}}});}catch(RuntimeException denied){ui(new Runnable(){public void run(){if(token==generation){begin("Aplicații recente");root.addView(text("Lista nu este disponibilă. Serviciul root Leo trebuie să fie pornit.",17),new android.widget.LinearLayout.LayoutParams(-1,0,1));footer("","","Înapoi");}}});}}});}
 private void render(){leo.clear();ArrayList<String> labels=new ArrayList<>();labels.add("Acasă Leo\nRevino la shell");for(int id:HomeAccess.get(this,"recent"))if(!AppCatalog.settingsOnly(id)){leo.add(id);labels.add(AppCatalog.NAMES[id]+"\nRecent în Leo");}for(TaskActions.Entry e:tasks)labels.add(e.label+"\nAplicație Android");list("Aplicații recente",labels,0,new Choice(){public void pick(int at){if(at==0)home();else if(at<=leo.size()){HomeAccess.open(RecentAppsActivity.this,leo.get(at-1));finish();}else switchTo(tasks.get(at-1-leo.size()));}},"Opțiuni",new Runnable(){public void run(){int at=selection();if(at<=0){home();return;}if(at<=leo.size()){HomeAccess.open(RecentAppsActivity.this,leo.get(at-1));finish();return;}final TaskActions.Entry entry=tasks.get(Math.min(tasks.size()-1,at-1-leo.size()));options(entry.label,new String[]{"Comută la aplicație","Închide fereastra"},new Choice(){public void pick(int action){if(action==0)switchTo(entry);else options("Închizi fereastra?",new String[]{"Păstrează","Închide"},new Choice(){public void pick(int yes){if(yes==1)worker.execute(new Runnable(){public void run(){boolean ok=false;try{ok=TaskActions.close(RecentAppsActivity.this,entry.id);}catch(Exception ignored){}final boolean done=ok;ui(new Runnable(){public void run(){notice(done?"Fereastră închisă":"Închidere indisponibilă");show();}});}});}});}});}});}
 private int selection(){for(int i=0;i<root.getChildCount();i++)if(root.getChildAt(i) instanceof android.widget.ListView)return ((android.widget.ListView)root.getChildAt(i)).getSelectedItemPosition();return 0;}
 private void switchTo(TaskActions.Entry task){try{TaskActions.open(this,task.id);finish();}catch(RuntimeException fail){notice("Aplicația nu mai este disponibilă");show();}}
 private void home(){startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP));finish();}
}
